from textkit.articles import article_url


def test_repeated_spaces_collapse():
    assert article_url("Hello   World") == "/articles/hello-world"


def test_tabs_and_punctuation():
    assert article_url(" Big\tNews!  Today ") == "/articles/big-news-today"

