import pytest

from settings_app.loader import load_settings


@pytest.mark.parametrize("value", ["false", "0", "no", "FALSE", " off "])
def test_false_values_disable_debug(value):
    assert load_settings({"APP_DEBUG": value})["debug"] is False


@pytest.mark.parametrize("value", ["true", "1", "yes", "On"])
def test_true_values_enable_debug(value):
    assert load_settings({"APP_DEBUG": value})["debug"] is True
